-- Hand-written: proforma withdraw (ADM-INV-10, owner decision 2026-10-30): the view rule for tax and export invoices only, a proforma's void rules, no view or send after a void, generated by scripts/write-triggers.ts from src/triggers.ts.
DROP TRIGGER `documents_viewed_no_void`;
--> statement-breakpoint
CREATE TRIGGER `documents_viewed_no_void` BEFORE UPDATE OF status ON `documents` WHEN NEW.status = 'void' AND OLD.status <> 'void' AND OLD.viewed_at IS NOT NULL AND OLD.type IN ('tax_invoice', 'export_invoice') BEGIN SELECT RAISE(ABORT, 'documents_viewed_no_void: a document the client has opened in the portal is never voided; a credit note corrects it'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_proforma_withdraw` BEFORE UPDATE OF status ON `documents` WHEN NEW.status = 'void' AND OLD.status <> 'void' AND OLD.type = 'proforma' AND (OLD.status <> 'issued' OR OLD.paid_minor <> 0 OR OLD.credited_minor <> 0 OR EXISTS (SELECT 1 FROM advance_receipts r WHERE r.proforma_id = OLD.id) OR EXISTS (SELECT 1 FROM documents x WHERE x.parent_id = OLD.id) OR NEW.void_reason IS NULL OR length(trim(NEW.void_reason)) = 0 OR length(NEW.void_reason) > 500) BEGIN SELECT RAISE(ABORT, 'documents_proforma_withdraw: a proforma is voided or withdrawn only while issued, with nothing paid or credited, no payment received, nothing made from it, and a reason'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_void_no_view` BEFORE UPDATE OF viewed_at ON `documents` WHEN OLD.status = 'void' AND NEW.viewed_at IS NOT OLD.viewed_at AND OLD.type IN ('proforma', 'tax_invoice', 'export_invoice') BEGIN SELECT RAISE(ABORT, 'documents_void_no_view: the portal view of a void document is never set or changed'); END;
--> statement-breakpoint
CREATE TRIGGER `document_sends_not_void` BEFORE INSERT ON `document_sends` WHEN EXISTS (SELECT 1 FROM documents d WHERE d.id = NEW.document_id AND d.type IN ('proforma', 'tax_invoice', 'export_invoice') AND (d.status = 'void' OR d.voided_at IS NOT NULL)) BEGIN SELECT RAISE(ABORT, 'document_sends_not_void: a void document is never sent'); END;
